head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[calendar > P > accessibility]<br/>Calendar 컴포넌트에 웹접근성 지원 기능을 일괄적으로 적용할지 설정합니다.",
    "validation" : [
        "미설정(기본값 false) 시 Calendar 컴포넌트에 웹접근성 지원 기능을 일괄적으로 적용하지 않습니다.",
        "true 설정 시 Calendar 컴포넌트에 웹접근성 지원 기능을 일괄적으로 적용합니다.",
        "true 설정 시 renderType='native', displayDayType='textNative', focusOnOuterDiv='true', cancelButtonShow='true', footerDiv='true' 가 강제로 설정됩니다.",
        "true 설정 시 달력 테이블에 role='grid', 행에 role='row', 날짜 셀에 role='gridcell', 요일 헤더에 role='columnheader' ARIA 역할이 부여됩니다.",
        "true 설정 시 각 날짜 셀에 aria-selected 속성이 부여되어 선택 상태를 스크린리더가 인식할 수 있습니다.",
        "true 설정 시 요일 헤더가 'th' 시맨틱 태그에 scope='col' 속성으로 렌더링되며, 요일명은 축약형 텍스트로 표시됩니다.",
        "true 설정 시 날짜 셀 내부에 'button' 요소 대신 텍스트만 직접 출력됩니다.",
        "true 설정 시 캘린더 최외곽 'div' 에 tabIndex='0' 이 부여되어 키보드 포커스를 수신할 수 있습니다.",
        "true 설정 시 방향키(상/하/좌/우)를 통한 날짜 셀 간 포커스 이동이 활성화됩니다.",
        "true 설정 시 캘린더에 대한 onfocus 이벤트 리스너가 등록되지 않아 포커스 시 선택 셀로 자동 이동하는 동작이 비활성화됩니다.",
        "true 설정 시 초기 렌더링 시 선택된 셀에 자동 포커스가 이동하지 않습니다.",
        "true 설정 시 연/월/시/분/초 입력창이 'select' 요소로 렌더링됩니다.",
        "true 설정 시 Footer 영역이 'table' 대신 'div' 구조로 렌더링되며, 취소 버튼이 표시됩니다.",        
        "accessibility=true 이면 Enter 키 입력 시 헤더 네비게이션 버튼(이전년, 다음년, 이전월, 다음월)에 대한 클릭 이벤트 처리가 건너뛰어집니다."
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        accessibility : con_accessibility.getText(),
        calendarValueType : "yearMonthDateTime"
    }

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onclick"]);

    await $c.gcm.createBasicCalendar(cList, eList);
}



scwin.getOptions = function () {
    let isOn = (target1.options.accessibility === true);

    // validation: 미설정(기본값 false) 시 적용하지 않음 / true 설정 시 일괄 적용
    wf_body_bottom.getObj("scwin").setReturnValue("[웹접근성 일괄 적용 여부] " + (isOn ? "적용됨" : "적용되지 않음") + " (accessibility=" + target1.options.accessibility + ")");

    // validation: true 설정 시 renderType='native', displayDayType='textNative', focusOnOuterDiv='true', cancelButtonShow='true', footerDiv='true' 가 강제로 설정됨
    wf_body_bottom.getObj("scwin").setReturnValue("[강제 설정 옵션] renderType=" + target1.options.renderType + ", displayDayType=" + target1.options.displayDayType + ", focusOnOuterDiv=" + target1.options.focusOnOuterDiv + ", cancelButtonShow=" + target1.options.cancelButtonShow + ", footerDiv=" + target1.options.footerDiv);
}



scwin.getRoleInfo = function () {
    let calendarRender = target1.render;

    let tableElement = calendarRender.querySelector('table');
    let trElement = calendarRender.querySelector('tr');
    let thElement = calendarRender.querySelector('th[class*="w2calendar_col_day_text"]');
    let tdElement = calendarRender.querySelector('td[class*="w2calendar_col_date"]');

    // validation: 달력 테이블에 role='grid', 행에 role='row', 날짜 셀에 role='gridcell', 요일 헤더에 role='columnheader' ARIA 역할이 부여됨
    if (tableElement && trElement && thElement && tdElement) {
        let allRoleApplied = (tableElement.getAttribute('role') === 'grid'
            && trElement.getAttribute('role') === 'row'
            && thElement.getAttribute('role') === 'columnheader'
            && tdElement.getAttribute('role') === 'gridcell');
        wf_body_bottom.getObj("scwin").setReturnValue("[ARIA 역할(role) 부여 여부] " + (allRoleApplied ? "모두 부여됨" : "미부여 또는 다른 값") + " (table=" + tableElement.getAttribute('role') + ", tr=" + trElement.getAttribute('role') + ", th=" + thElement.getAttribute('role') + ", td=" + tdElement.getAttribute('role') + ")");
    }

    // validation: 요일 헤더가 'th' 시맨틱 태그에 scope='col' 속성으로 렌더링되며, 요일명은 축약형 텍스트로 표시됨
    if (thElement)
        wf_body_bottom.getObj("scwin").setReturnValue("[요일 헤더 시맨틱/축약형 표시] scope=" + thElement.getAttribute('scope') + ", 요일명='" + thElement.textContent + "'");
}



scwin.getDayCellInfo = function () {
    let calendarRender = target1.render;

    let selectedCell = calendarRender.querySelector('td[class*="w2calendar_selected"]');
    let firstDateCell = calendarRender.querySelector('td[class*="w2calendar_col_date"]');

    // validation: 각 날짜 셀에 aria-selected 속성이 부여되어 선택 상태를 스크린리더가 인식할 수 있음
    if (selectedCell) {
        let ariaSelected = selectedCell.getAttribute('aria-selected');
        wf_body_bottom.getObj("scwin").setReturnValue("[선택 상태 스크린리더 인식] 선택된 날짜('" + selectedCell.textContent.trim() + "') 셀 aria-selected=" + ariaSelected);
    }

    // validation: 날짜 셀 내부에 'button' 요소 대신 텍스트만 직접 출력됨
    if (selectedCell) {
        let hasButton = (selectedCell.querySelector('button') !== null);
        wf_body_bottom.getObj("scwin").setReturnValue("[선택 셀 - button 대신 텍스트만 출력] " + (hasButton ? "button 요소 포함" : "텍스트만 직접 출력 ('" + selectedCell.textContent.trim() + "')"));
    }
    if (firstDateCell) {
        let hasButton = (firstDateCell.querySelector('button') !== null);
        wf_body_bottom.getObj("scwin").setReturnValue("[일반 날짜 셀 - button 대신 텍스트만 출력] " + (hasButton ? "button 요소 포함" : "텍스트만 직접 출력 ('" + firstDateCell.textContent.trim() + "')"));
    }
}



scwin.getOuterDivInfo = function () {
    let calendarRender = target1.render;

    // validation: 캘린더 최외곽 'div' 에 tabIndex='0' 이 부여되어 키보드 포커스를 수신할 수 있음
    let tabIdx = calendarRender.getAttribute('tabIndex');
    let canFocus = (calendarRender.tagName.toLowerCase() === 'div' && tabIdx === '0');
    wf_body_bottom.getObj("scwin").setReturnValue("[최외곽 div 키보드 포커스 수신] " + (canFocus ? "수신 가능" : "수신 불가") + " (최외곽 태그=" + calendarRender.tagName.toLowerCase() + ", tabIndex=" + tabIdx + ")");
}



scwin.getSelectElementInfo = function () {
    let calendarRender = target1.render;

    // validation: 연/월/시/분/초 입력창이 'select' 요소로 렌더링됨
    let labels = ['연', '월', '시', '분', '초'];
    let selectors = ['select[id*="_year"]', 'select[id*="_month"]', 'select[id*="_hour"]', 'select[id*="_minute"]', 'select[id*="_second"]'];
    let asSelect = labels.filter((lbl, i) => calendarRender.querySelector(selectors[i]) !== null);
    wf_body_bottom.getObj("scwin").setReturnValue("[연/월/시/분/초 입력창 select 렌더링 여부] select 로 렌더링된 입력창: " + (asSelect.length ? asSelect.join('/') : "없음"));
}



scwin.getFooterInfo = function () {
    let calendarRender = target1.render;

    let footerDiv = calendarRender.querySelector('div.w2calendar_footer, div[class*="w2calendar_footer_native"]');
    let footerTable = calendarRender.querySelector('table.w2calendar_footer');
    let cancelButton = calendarRender.querySelector('[class*="w2calendar_time_cancel"]');

    // validation: Footer 영역이 'table' 대신 'div' 구조로 렌더링됨
    let footerStructure = footerDiv ? "div 구조" : (footerTable ? "table 구조" : "Footer 없음");
    wf_body_bottom.getObj("scwin").setReturnValue("[Footer 영역 렌더링 구조] " + footerStructure);

    // validation: 취소 버튼이 표시됨
    wf_body_bottom.getObj("scwin").setReturnValue("[취소 버튼 표시 여부] " + (cancelButton ? "표시됨 ('" + cancelButton.textContent + "')" : "표시되지 않음"));
}



scwin.btn_getInfo_onclick = function (e) {
    scwin.getOptions();
    scwin.getOuterDivInfo();
    scwin.getRoleInfo();
    scwin.getDayCellInfo();
    scwin.getSelectElementInfo();
    scwin.getFooterInfo();
}



scwin.target1_onclick = function (e) {
    setTimeout(() => {
        scwin.getOptions();
    }, 100);
}
